/* 16 flowchart */
.flow{position:relative;width:360px;height:420px;flex:none}
.flow svg.wires{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.wire{fill:none;stroke:rgba(var(--fg-rgb),.18);stroke-width:1;transition:stroke .4s ease}
.wire.lit{stroke:var(--accent)}
.wire-flow{fill:none;stroke:var(--accent);stroke-width:1.5;stroke-dasharray:4 10;opacity:0;transition:opacity .3s;animation:flowdash 1s linear infinite}
.wire-flow.lit{opacity:1}
@keyframes flowdash{to{stroke-dashoffset:-14}}
.fnode{position:absolute;text-align:left}
.fnode .node{flex-direction:column;align-items:stretch;gap:6px;padding:10px 12px;width:100%}
.fnode .ftop{display:flex;align-items:center;gap:8px}
.fnode .ftop .ms{color:var(--muted);font-size:16px;transition:color .3s}
.fnode .node.on .ftop .ms{color:var(--accent)}
.fnode .ft{font-weight:600;font-size:14px;transition:color .3s}
.fnode .node.on .ft{color:var(--accent)}
.fnode .fd{font-size:12px;color:var(--muted)}
.cond{display:flex;flex-wrap:wrap;align-items:center;gap:4px;font-size:12px;color:var(--muted)}
.cond .tag{font-family:var(--mono);font-size:11px}
.blabel{position:absolute;font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;color:var(--muted);background:var(--bg);padding:0 4px;transition:color .3s}
.blabel.lit{color:var(--accent)}

/* automation canvas dropdowns */
.fsel{cursor:pointer;display:inline-flex;align-items:center;gap:2px;transition:box-shadow .2s}
.fsel .ms{font-size:12px;color:var(--muted)}
.fsel.open,.fsel:focus-visible{box-shadow:0 0 0 1.5px var(--accent);outline:none}
.f-menu{position:absolute;z-index:6;width:200px;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px) scale(.98);transform-origin:top left;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.f-menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.f-mi{display:flex;align-items:center;gap:10px;width:100%;padding:8px 10px;font-size:13px;font-weight:500;color:var(--text);text-align:left;transition:background-color .15s}
.f-mi:hover{background:var(--chip)}
.f-mi .d{margin-left:auto;font-size:12px;font-weight:400;color:var(--muted)}
.f-mi .ms{opacity:0;color:var(--accent)}
.f-mi.sel .ms{opacity:1}
[data-style="soft"] .f-menu{border-radius:14px;border-color:var(--line)}
[data-style="soft"] .f-mi{border-radius:9px}
[data-style="soft"] .fsel{border-radius:7px}

/* ---------- 16 flowchart ---------- */
{
  const flow = $('#flow');
  const nodes = Object.fromEntries($$('.fnode', flow).map(n => [n.dataset.node, n]));
  const setOn = (n, on) => { n.classList.toggle('on', on); n.querySelector('.node').classList.toggle('on', on); };
  $$('.fnode .node', flow).forEach(b => b.addEventListener('click', () => {
    const n = b.closest('.fnode'); const on = !n.classList.contains('on');
    Object.values(nodes).forEach(x => setOn(x, false)); setOn(n, on); Sound.play('select');
  }));
  let ts = [];
  function run(){
    ts.forEach(clearTimeout); ts = [];
    Object.values(nodes).forEach(x => setOn(x, false));
    $$('.wire,.wire-flow,.blabel', flow).forEach(w => w.classList.remove('lit'));
    const seq = [
      () => { setOn(nodes.trigger, true); Sound.play('pop'); },
      () => { $('#w1').classList.add('lit'); $('#wf1').classList.add('lit'); Sound.play('tick'); },
      () => { setOn(nodes.if, true); Sound.play('pop'); },
      () => { $('#w2').classList.add('lit'); $('#wf2').classList.add('lit'); $('#bl-yes').classList.add('lit'); Sound.play('tick'); },
      () => { setOn(nodes.yes, true); Sound.play('done'); },
      () => { $$('.wire-flow', flow).forEach(w => w.classList.remove('lit')); }
    ];
    seq.forEach((fn, i) => ts.push(setTimeout(fn, i * 650 + (i === 5 ? 1600 : 0))));
  }
  $('#flow-run').addEventListener('click', run);
}

/* ---------- flow menus ---------- */
{
  const flow = $('#flow'), menu = document.createElement('div'); menu.className = 'f-menu'; menu.setAttribute('role', 'listbox'); flow.appendChild(menu);
  const opts = { type:[['Website','Marketing site'],['Product','App or dashboard'],['Brand','Identity work'],['Development','Build only']], plan:[['Retainer','Monthly'],['Project','Fixed scope'],['Sprint','Two weeks']] };
  let cur = null;
  function open(tag){
    cur = tag; const k = tag.dataset.k, v = tag.firstChild.textContent;
    menu.innerHTML = opts[k].map(o => `<button class="f-mi ${o[0] === v ? 'sel' : ''}" role="option" data-v="${o[0]}"><span>${o[0]}</span><span class="d">${o[1]}</span>${ic('check','sm')}</button>`).join('');
    const fr = flow.getBoundingClientRect(), tr = tag.getBoundingClientRect();
    menu.style.left = Math.max(0, Math.min(fr.width - 236, tr.left - fr.left)) + 'px'; menu.style.top = (tr.bottom - fr.top + 6) + 'px';
    $$('.fsel', flow).forEach(t => t.classList.toggle('open', t === tag)); menu.classList.add('show'); Sound.play('open');
  }
  function close(){ if (!cur) return; menu.classList.remove('show'); $$('.fsel', flow).forEach(t => t.classList.remove('open')); cur = null; }
  flow.addEventListener('click', e => {
    const t = e.target.closest('.fsel'), mi = e.target.closest('.f-mi');
    if (t){ e.stopPropagation(); e.preventDefault(); cur === t ? close() : open(t); }
    else if (mi){ e.stopPropagation(); cur.firstChild.textContent = mi.dataset.v; Sound.play('select'); close(); }
  }, true);
  flow.addEventListener('keydown', e => { const t = e.target.closest('.fsel'); if (t && (e.key === 'Enter' || e.key === ' ')){ e.preventDefault(); e.stopPropagation(); open(t); } if (e.key === 'Escape') close(); });
  document.addEventListener('pointerdown', e => { if (cur && !menu.contains(e.target) && !e.target.closest('.fsel')) close(); });
}
